it('TID-WEB-003 tasker sends clarity + respectfulness (not quality/communication)', async () => {
  const taskerBooking: Booking = {
    ...makeBooking(),
    id: 'bkrview-1',
    status: 'COMPLETED',
    customer_id: 'cust-1',
    tasker_id: 'tasker-1',
  };

  const session = makeSession({ user: { ...makeUser(), id: 'tasker-1', role: 'TASKER' } });

  const apiClient = createMockApiClient({
    getMyProfile: vi.fn().mockResolvedValue(makeProfile()),
    listBookings: vi.fn().mockImplementation(async (_token, params) => {
      if (params?.status === 'COMPLETED')
        return { data: [taskerBooking], cursor: { next: null, has_more: false } };
      return { data: [], cursor: { next: null, has_more: false } };
    }),
    submitReview: vi.fn().mockResolvedValue(makeReview()),
  });

  const { App } = await import('../../src/App');
  render(<App apiClient={apiClient} initialRoute="/booking/safety" initialSession={session} />);

  // Switch to Completed tab
  const completedTab = await screen.findByRole('tab', { name: 'Completed' });
  fireEvent.click(completedTab);

  await screen.findByText(/bkrview/i);

  // Click Leave Review
  fireEvent.click(screen.getByRole('menuitem', { name: /Leave Review/i }));

  // Fill comment
  await screen.findByRole('heading', { name: /Leave a Review/i });
  fireEvent.change(screen.getByLabelText('Comment'), { target: { value: 'Good customer.' } });
  fireEvent.click(screen.getByRole('button', { name: 'Submit Review' }));

  await waitFor(() => {
    expect(apiClient.submitReview).toHaveBeenCalledWith(
      'access-token',
      'bkrview-1',
      expect.objectContaining({
        punctuality_rating: 5,
        clarity_rating: 5,
        respectfulness_rating: 5,
        comment: 'Good customer.',
      }),
    );
    const call = (apiClient.submitReview as ReturnType<typeof vi.fn>).mock.calls[0][2];
    expect(call).not.toHaveProperty('quality_rating');
    expect(call).not.toHaveProperty('communication_rating');
  });
});

